values.content:
=You are a conversational AI training data expert. Generate high-quality chatbot training data for the specified topic and domain.

Topic: {{ $json.body.topic }}
Domain: {{ $json.body.domain || 'General' }}
Tone: {{ $json.body.tone || 'Professional and friendly' }}
Language: {{ $json.body.language || 'English' }}
Count: {{ $json.body.count || 20 }} Q&A pairs

Generate:
1. **Q&A Pairs** — Diverse question-answer pairs covering the topic comprehensively
2. **Intents** — Named intents with example utterances
3. **Entities** — Named entities that should be extracted

Return JSON:
{
  "qa_pairs": [
    {"id": 1, "question": "...", "answer": "...", "intent": "...", "variations": ["alt question 1", "alt question 2"]}
  ],
  "intents": [
    {"name": "intent_name", "description": "...", "examples": ["utterance1", "utterance2", "utterance3"]}
  ],
  "entities": [
    {"name": "entity_name", "type": "...", "examples": ["value1", "value2"]}
  ],
  "fallback_responses": ["I'm not sure I understand...", "Could you rephrase?"],
  "greeting_responses": ["Hello! How can I help?"],
  "topic_coverage": "percentage estimate of topic coverage",
  "total_qa": 20
}

parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { qa_pairs: [{ id: 1, question: 'Parse error', answer: aiResponse, intent: 'error' }], intents: [], entities: [] };
}

const qaPairs = parsed.qa_pairs || [];
return qaPairs.map(qa => ({
  json: {
    date: new Date().toISOString().split('T')[0],
    topic: items[0].json.body?.topic || '',
    domain: items[0].json.body?.domain || 'General',
    id: qa.id || 0,
    question: qa.question || '',
    answer: qa.answer || '',
    intent: qa.intent || '',
    variations: Array.isArray(qa.variations) ? qa.variations.join(' | ') : '',
    totalQA: parsed.total_qa || qaPairs.length,
    intentsCount: (parsed.intents || []).length,
    entitiesCount: (parsed.entities || []).length,
    topicCoverage: parsed.topic_coverage || ''
  }
}));
